theory.code:
@RestController -> @Controller -> @Component

@Controller     dodaje obsluge Spring MVC (routing zadan HTTP)
@RestController dodatkowo laczy to z @ResponseBody (API zwracajace dane, nie widoki HTML)

@Service        -> @Component (BEZ dodatkowego zachowania - to CZYSTA semantyka)
@Repository     -> @Component + automatyczne tlumaczenie wyjatkow (jedyny stereotyp z bonusem)

@Component class GenericComponent {}
@Service class OrderCalculationService {}
@Repository class OrderRepository {}
@Controller class OrderController {}

// Wszystkie 4 zachowuja sie IDENTYCZNIE przy pobieraniu z kontekstu:
GenericComponent c = context.getBean(GenericComponent.class);
OrderCalculationService s = context.getBean(OrderCalculationService.class);
OrderRepository r = context.getBean(OrderRepository.class);
OrderController ctrl = context.getBean(OrderController.class);
// Kontener NIE ROZROZNIA stereotypow przy tworzeniu beanow
